package com.fasterxml.jackson.databind.deser;

import com.fasterxml.jackson.annotation.JsonFormat;
import com.fasterxml.jackson.annotation.JsonIgnoreProperties;
import com.fasterxml.jackson.annotation.JsonTypeInfo;
import com.fasterxml.jackson.annotation.ObjectIdGenerator;
import com.fasterxml.jackson.annotation.ObjectIdGenerators;
import com.fasterxml.jackson.annotation.ObjectIdResolver;
import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser.NumberType;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.deser.impl.*;
import com.fasterxml.jackson.databind.deser.std.StdDelegatingDeserializer;
import com.fasterxml.jackson.databind.deser.std.StdDeserializer;
import com.fasterxml.jackson.databind.exc.IgnoredPropertyException;
import com.fasterxml.jackson.databind.introspect.*;
import com.fasterxml.jackson.databind.introspect.Annotated;
import com.fasterxml.jackson.databind.introspect.BeanDescription;
import com.fasterxml.jackson.databind.introspect.BeanPropertyMap;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.type.ClassKey;
import com.fasterxml.jackson.databind.util.*;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Constructor;
import java.lang.reflect.InvocationTargetException;
import java.math.*;
import java.util.*;
import java.util.Collections;
import java.util.Map;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

public class BeanDeserializerBase_deserializeFromDouble_TriageGen1Test {

    private JsonParser p;
    private DeserializationContext ctxt;
    private ValueInstantiator instantiator;
    private JsonDeserializer<Object> delegateDeserializer;
    private TestBeanDeserializerBase deserializer;

    // Concrete implementation to test protected method
    private static class TestBeanDeserializerBase extends BeanDeserializerBase {
        protected TestBeanDeserializerBase(BeanDeserializerBuilder builder, BeanDescription beanDesc, BeanPropertyMap properties, Map<String, SettableBeanProperty> backRefs, Set<String> ignorableProps, boolean ignoreAllUnknown, boolean hasViews) {
            super(builder, beanDesc, properties, backRefs, ignorableProps, ignoreAllUnknown, hasViews);
        }

        // Helper to expose protected fields for testing via reflection or direct assignment if possible
        // Since we are in the same package, we can access protected members
        public void setInternalState(ValueInstantiator instantiator, JsonDeserializer<Object> delegate, InjectableValues injectables) {
            this._valueInstantiator = instantiator;
            this._delegateDeserializer = delegate;
            this._injectables = injectables;
        }

        @Override
        public JsonDeserializer<Object> unwrappingDeserializer(NameTransformer unwrapper) { return null; }
        @Override
        public BeanDeserializerBase withObjectIdReader(ObjectIdReader oir) { return this; }
        @Override
        public BeanDeserializerBase withIgnorableProperties(java.util.Set<String> ignorableProps) { return this; }
        @Override
        public BeanDeserializerBase withBeanProperties(BeanPropertyMap props) { return this; }
        @Override
        protected BeanDeserializerBase asArrayDeserializer() { return this; }
        @Override
        public void resolve(DeserializationContext ctxt) throws JsonMappingException {}
        @Override
        protected Object _deserializeUsingPropertyBased(JsonParser p, DeserializationContext ctxt) throws IOException, com.fasterxml.jackson.core.JsonProcessingException { return null; }
    }

    @Before
    public void setup() {
        p = mock(JsonParser.class);
        ctxt = mock(DeserializationContext.class);
        instantiator = mock(ValueInstantiator.class);
        delegateDeserializer = mock(JsonDeserializer.class);

        // Mocking Builder and BeanDescription for constructor
        BeanDeserializerBuilder builder = mock(BeanDeserializerBuilder.class);
        BeanDescription beanDesc = mock(BeanDescription.class);

        deserializer = new TestBeanDeserializerBase(builder, beanDesc, null, null, null, false, false);
        deserializer.setInternalState(instantiator, null, null);
    }

    @Test
    public void testDeserializeFromDouble_DirectInstantiator() throws IOException {
        when(p.getNumberType()).thenReturn(NumberType.DOUBLE);
        when(p.getDoubleValue()).thenReturn(123.45);
        when(instantiator.createFromDouble(eq(ctxt), eq(123.45))).thenReturn("Success");

        Object result = deserializer.deserializeFromDouble(p, ctxt);

        assertEquals("Success", result);
    }

    @Test
    public void testDeserializeFromDouble_FloatTypeDirectInstantiator() throws IOException {
        when(p.getNumberType()).thenReturn(NumberType.FLOAT);
        when(p.getDoubleValue()).thenReturn(1.2f);
        when(instantiator.createFromDouble(eq(ctxt), eq(1.2f))).thenReturn("FloatSuccess");

        Object result = deserializer.deserializeFromDouble(p, ctxt);

        assertEquals("FloatSuccess", result);
    }

    @Test
    public void testDeserializeFromDouble_WithDelegateAndCanCreateFromDouble() throws IOException {
        when(p.getNumberType()).thenReturn(NumberType.DOUBLE);
        deserializer.setInternalState(instantiator, delegateDeserializer, null);

        when(instantiator.canCreateFromDouble()).thenReturn(true);
        when(delegateDeserializer.deserialize(p, ctxt)).thenReturn("DelegatedObj");
        when(instantiator.createFromDouble(eq(ctxt), anyDouble())).thenReturn("DelegatedObj");

        Object result = deserializer.deserializeFromDouble(p, ctxt);

        assertEquals("DelegatedObj", result);
    }

    @Test
    public void testDeserializeFromDouble_WithDelegateAndCannotCreateFromDouble_WithInjectables() throws IOException {
        when(p.getNumberType()).thenReturn(NumberType.DOUBLE);
        InjectableValues injectables = mock(InjectableValues.class);
        deserializer.setInternalState(instantiator, delegateDeserializer, injectables);

        when(instantiator.canCreateFromDouble()).thenReturn(false);
        Object delegatedBean = new Object();
        when(delegateDeserializer.deserialize(p, ctxt)).thenReturn(delegatedBean);
        when(instantiator.createUsingDelegate(eq(ctxt), eq(delegatedBean))).thenReturn(delegatedBean);

        Object result = deserializer.deserializeFromDouble(p, ctxt);

        assertEquals(delegatedBean, result);
        // Verify injectValues was called (indirectly via the logic)
        // Note: injectValues is protected, we check if it runs without error if we could, 
        // but here we verify return value.
    }

    @Test
    public void testDeserializeFromDouble_NonNumericTypeWithDelegate() throws IOException {
        // If type is NOT Double/Float (e.g. INT), but delegate exists
        when(p.getNumberType()).thenReturn(NumberType.INT);
        deserializer.setInternalState(instantiator, delegateDeserializer, null);

        when(delegateDeserializer.deserialize(p, ctxt)).thenReturn("IntDelegate");
        when(instantiator.createUsingDelegate(eq(ctxt), eq("IntDelegate"))).thenReturn("IntDelegate");

        Object result = deserializer.deserializeFromDouble(p, ctxt);

        assertEquals("IntDelegate", result);
    }

    @Test
    public void testDeserializeFromDouble_NoDelegateAndNoNumericType() throws IOException {
        when(p.getNumberType()).thenReturn(NumberType.INT);
        deserializer.setInternalState(instantiator, null, null);

        when(p.getNumberValue()).thenReturn(10);
        when(ctxt.handleMissingInstantiator(any(), eq(p), anyString(), eq(10L))).thenReturn("Missing");

        Object result = deserializer.deserializeFromDouble(p, ctxt);

        assertEquals("Missing", result);
    }

    @Test
    public void testDeserializeFromDouble_NonNumericTypeWithNoDelegate() throws IOException {
        when(p.getNumberType()).thenReturn(NumberType.LONG);
        deserializer.setInternalState(instantiator, null, null);

        when(p.getNumberValue()).thenReturn(50L);
        when(ctxt.handleMissingInstantiator(any(), eq(p), anyString(), eq(50L))).thenReturn("Error");

        Object result = deserializer.deserializeFromDouble(p, ctxt);

        assertEquals("Error", result);
    }
}
